def _seq(ann, task):
    ov_ids = CORPUS[CORPUS.in_overlap].ticket_id.tolist()
    piv = ann[ann.ticket_id.isin(ov_ids)].pivot(index='ticket_id', columns='annotator', values=task)
    return ([piv[a].tolist() for a in ['A1', 'A2', 'A3']], ov_ids)

def paired_delta_ci():
    i1, ov = _seq(ANN[1], 'intent')
    i2, _ = _seq(ANN[2], 'intent')
    rng, N = (np.random.default_rng(7), len(ov))
    diffs = np.array([fleiss_kappa([[l[k] for k in cols] for l in i2]) - fleiss_kappa([[l[k] for k in cols] for l in i1]) for cols in (rng.integers(0, N, N) for _ in range(500))])
    lo, hi = np.percentile(diffs, [2.5, 97.5])
    return (diffs.mean(), lo, hi)
D_MEAN, D_LO, D_HI = paired_delta_ci()
