def esc(s):
    return html.escape(str(s), quote=True)

def b64img(name):
    raw = open(f'{FIG}/{name}', 'rb').read()
    return 'data:image/png;base64,' + base64.b64encode(raw).decode()

def votes(tid, rnd):
    sub = ANN[rnd][ANN[rnd].ticket_id == tid]
    if sub.empty:
        return '<span class="novote">no label</span>'
    out, intents = ([], [])
    for _, a in sub.sort_values('annotator').iterrows():
        intents.append(a.intent)
        out.append(f'<span class="v"><b>{a.annotator}</b> {INTENT_AB[a.intent]}·{SENT_AB[a.sentiment]}</span>')
    split = len(set(intents)) > 1 or len(sub) < 3
    dot = '<span class="dot"></span>' if split else ''
    cls = 'votes split' if len(set(intents)) > 1 else 'votes'
    return f'''{dot}<span class="{cls}">{''.join(out)}</span>'''

def finallab(tid):
    r = ADJ.loc[tid]
    rw_i, rw_s = (bool(r.intent_rework), bool(r.sentiment_rework))
    mark = '<span class="rwmark" title="corrected at tier-2 review">✳</span>' if rw_i or rw_s else ''
    return f'<b>{INTENT_AB[r.final_intent]}</b>·{SENT_AB[r.final_sentiment]}{mark}'

def pct(x, d=1):
    return f'{100 * x:.{d}f}%'

def k4(x):
    return f'{x:.4f}'

def dlta(a, b, d=3, unit=''):
    v = b - a
    sign = '+' if v >= 0 else '−'
    return f'<span class="delta">▲ {sign}{abs(v):.{d}f}{unit}</span>'
