stat_tbl = ''.join((f'<tr><td>{n}<span class="dim" style="display:block;font-size:11px">{d}</span></td><td class="n dim">{a:.4f} <span class="dim">{ca}</span></td><td class="n"><b>{b:.4f}</b> <span class="dim">{cb}</span></td><td class="n">{dlta(a, b)}</td></tr>' for n, d, a, b, ca, cb in stat_rows))
gold63 = {a: (R1['gold_accuracy'][a], R2['gold_accuracy'][a]) for a in ('A1', 'A2', 'A3')}
HTML_BODY = f'''<!doctype html>\n<html lang="en"><head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>GuidelineForge — Annotation QA Program Report</title>\n<meta name="description" content="Designing, measuring and repairing an annotation\nquality pipeline: 600 support tickets, two labeling rounds, three QA tiers and one\nguideline revision — with every statistic recomputed from raw labels.">\n<style>{CSS}</style>\n</head>\n<body>\n<div class="topbar"></div>\n<div class="wrap">\n\n  <!-- ================= masthead ================= -->\n  <header>\n    <div class="mastrow">\n      <span class="kicker">GuidelineForge<span class="dotsep">·</span>Annotation\n      Quality Program</span>\n      <span class="right">Program Report · 25 Aug 2026 · Indore</span>\n    </div>\n    <h1>From arguments<br>to <em>agreement.</em></h1>\n    <p class="standfirst">Nine weeks, six hundred support tickets, three\n    annotators who could not stop disagreeing — and a five-rule guideline\n    revision that moved inter-annotator reliability from\n    {R1['fleiss_intent']:.2f} to {R2['fleiss_intent']:.2f} while cutting the\n    defects that agreement alone would never have caught. This is the full\n    account: the corpus, the method, the statistics, and the evidence drawer.</p>\n    <nav class="toc"><b>In this report</b>\n      <a href="#s1"><i>01</i>The corpus</a>\n      <a href="#s2"><i>02</i>Method</a>\n      <a href="#s3"><i>03</i>Results</a>\n      <a href="#s4"><i>04</i>Disagreement</a>\n      <a href="#s5"><i>05</i>Quality gates</a>\n      <a href="#s6"><i>06</i>Evidence drawer</a>\n      <a href="#s7"><i>07</i>Reproduce</a>\n      <a href="#s8"><i>08</i>Provenance</a>\n    </nav>\n    <div class="metabar">\n      <div><span class="mk">Program window</span><span class="mv">29 Jun – 24 Aug 2026\n        <small>2 rounds + calibration</small></span></div>\n      <div><span class="mk">Corpus</span><span class="mv">{DESIGN['corpus']} tickets\n        <small>{DESIGN['overlap']} blind triple overlap</small></span></div>\n      <div><span class="mk">Task</span><span class="mv">intent (8) + sentiment (3)\n        <small>ordinal distances</small></span></div>\n      <div><span class="mk">Crew</span><span class="mv">3 annotators\n        <small>+ QA lead &amp; auditor</small></span></div>\n      <div><span class="mk">Status</span><span class="mv">Shipped, v2 guidelines\n        <small>audit clean · rework {pct(QA['rework_rate_either'])}</small></span></div>\n    </div>\n    <div class="disclosure"><span class="dtag">Simulation disclosure</span>\n      <p>The three annotators are documented, seeded <b>simulation personas</b> —\n      failure modes modeled on common human error patterns, every bias listed in\n      §08 and in <span class="mono" style="font-size:12px">src/annotators.py</span>.\n      Everything downstream — labels, agreements, rework, audits — is real data\n      produced by the pipeline and recomputed on this page. No statistic here is\n      typed by hand.</p>\n    </div>\n\n    <table class="ledger">\n      <thead><tr><th style="width:31%">The ledger</th><th>Round 1 · v1 rules</th>\n        <th>Round 2 · v2 rules</th><th>Δ</th><th>Reading</th></tr></thead>\n      <tbody>\n      <tr><td class="mname">Fleiss’ κ — intent\n            <small>the program’s north star; gate ≥ 0.80</small></td>\n          <td class="num r1">{R1['fleiss_intent']:.4f}</td>\n          <td class="num r2">{R2['fleiss_intent']:.4f}</td>\n          <td>{dlta(R1['fleiss_intent'], R2['fleiss_intent'])}</td>\n          <td class="reading">met in R1, exceeded in R2; 95% CIs disjoint\n            ([{ci1[0]:.3f}, {ci1[1]:.3f}] vs [{ci2[0]:.3f}, {ci2[1]:.3f}])</td></tr>\n      <tr><td class="mname">Krippendorff’s α — sentiment\n            <small>ordinal distance; the metric that failed v1</small></td>\n          <td class="num r1">{R1['alpha_sentiment_ordinal']:.4f}</td>\n          <td class="num r2">{R2['alpha_sentiment_ordinal']:.4f}</td>\n          <td>{dlta(R1['alpha_sentiment_ordinal'], R2['alpha_sentiment_ordinal'])}</td>\n          <td class="reading">below the 0.667 floor in R1 — partial credit on\n            near-misses exposed severe, not borderline, errors</td></tr>\n      <tr><td class="mname">Fleiss’ κ — sentiment\n            <small>nominal, for reference</small></td>\n          <td class="num r1">{R1['fleiss_sentiment']:.4f}</td>\n          <td class="num r2">{R2['fleiss_sentiment']:.4f}</td>\n          <td>{dlta(R1['fleiss_sentiment'], R2['fleiss_sentiment'])}</td>\n          <td class="reading">crossed 0.80 only after the sarcasm rule shipped</td></tr>\n      <tr><td class="mname">Unanimous agreement — intent\n            <small>share of the 180-ticket overlap</small></td>\n          <td class="num r1">{pct(R1['unanimous_intent_overlap'])}</td>\n          <td class="num r2">{pct(R2['unanimous_intent_overlap'])}</td>\n          <td>{dlta(100 * R1['unanimous_intent_overlap'], 100 * R2['unanimous_intent_overlap'], 1, ' pts')}</td>\n          <td class="reading">one ticket in five needed adjudication in R1;\n            one in eighteen in R2</td></tr>\n      <tr><td class="mname">Final labels vs gold — intent / sentiment\n            <small>accuracy after adjudication, 72-item gold set</small></td>\n          <td class="num na">n/a</td>\n          <td class="num r2">{QA['final_gold_intent_acc']:.3f} / {QA['final_gold_sentiment_acc']:.3f}</td>\n          <td><span class="delta">—</span></td>\n          <td class="reading">the number a client actually buys; sentiment’s gap\n            is two tickets, both documented</td></tr>\n      <tr><td class="mname">Tier-2 rework — production\n            <small>share of single-labeled tickets sent back</small></td>\n          <td class="num na">n/a</td>\n          <td class="num r2">{pct(PROD_EITHER)} <span style="font-size:13px;font-weight:400;color:var(--mute)">({PROD_EITHER_N}/420)</span></td>\n          <td><span class="delta">—</span></td>\n          <td class="reading">28 of 600 tickets overall (4.7%); well under the 15–20% “healthy” ceiling;\n            above 30% would indict the instructions, not the crew</td></tr>\n      <tr><td class="mname">Tier-3 audit pass\n            <small>stratified sample, n = {QA['tier3_audit']['n']}\n            ({QA['tier3_audit']['n_gold_in_audit']} against gold)</small></td>\n          <td class="num na">n/a</td>\n          <td class="num r2">{pct(QA['tier3_audit']['pass_rate_overall'], 0)}</td>\n          <td><span class="delta">—</span></td>\n          <td class="reading">every sampled final label re-derived independently\n            from v2 and matched</td></tr>\n      </tbody>\n    </table>\n  </header>\n\n  <!-- ================= 01 corpus ================= -->\n  <section id="s1">\n    <div class="sec-head"><span class="sec-no">01</span><h2>The corpus</h2>\n      <span class="hintr">600 tickets · 520 real · 80 injected</span></div>\n    <div class="cols wide-l">\n      <div>\n        <p class="lede">Real customer-support tickets from the public Bitext\n        dataset (CC0), stratified onto eight intent classes — then deliberately\n        contaminated with five families of language that break annotation\n        programs.</p>\n        <p class="body">Agreement statistics are meaningless on easy data. So\n        {int((CORPUS.source != 'bitext').sum())} tickets were injected across\n        five engineered ambiguity families — sarcasm, mixed intents, polite\n        complaints, tone traps, bare fragments — and another\n        {int((CORPUS.augmentation != 'none').sum())} Bitext tickets had their\n        sentiment layer re-wrapped (deadpan phrasing over negative facts, and\n        vice versa). Every injection is logged in the augmentation manifest;\n        nothing is smuggled in.</p>\n        <h3>Label schema</h3>\n        <p class="body" style="font-size:15px">\n          <span class="chipwrap">\n          {' '.join((f'<span style="display:inline-block;border:1px solid var(--hair);background:var(--card);padding:3px 10px;margin:0 6px 8px 0;font:11px var(--mono)">{c}</span>' for c in sorted(INTENT_AB, key=list(INTENT_AB).index)))}\n          </span><br>\n          <span style="font:12px var(--sans);color:var(--mute)">sentiment —\n          ordinal: negative → neutral → positive&nbsp;&nbsp;·&nbsp;&nbsp;one\n          intent + one sentiment per ticket, no spans in this study</span></p>\n      </div>\n      <div>\n        <h3>Composition</h3>\n        <table class="mini">\n          <thead><tr><th>Slice</th><th>corpus</th><th>in overlap</th></tr></thead>\n          <tbody>{''.join(slice_tbl_rows)}</tbody>\n        </table>\n        <h3>Roles</h3>\n        <table class="mini">\n          <tbody>\n          <tr><td>Blind triple overlap</td><td class="n">{DESIGN['overlap']}</td></tr>\n          <tr><td class="dim">· calibration (seeded difficult)</td><td class="n dim">{DESIGN['calibration']}</td></tr>\n          <tr><td class="dim">· gold set (adjudicated)</td><td class="n dim">{DESIGN['gold']}</td></tr>\n          <tr><td class="dim">· random fill</td><td class="n dim">{DESIGN['overlap'] - DESIGN['calibration'] - DESIGN['gold']}</td></tr>\n          <tr><td>Production — rotated single labels</td><td class="n">420</td></tr>\n          <tr><td>Batches per round</td><td class="n">4 × 45</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </section>\n\n  <!-- ================= 02 method ================= -->\n  <section id="s2">\n    <div class="sec-head"><span class="sec-no">02</span><h2>Method</h2>\n      <span class="hintr">calibrate → gate → label → review → audit</span></div>\n    <div class="cols wide-l">\n      <div>\n        <ol class="steps">\n          <li><b>Calibration first.</b>\n            <p>48 seeded-difficult tickets, all three annotators, adjudicated\n            live with the QA lead. R1’s calibration log wrote the first draft of\n            every v2 rule.</p></li>\n          <li><b>A gate before production.</b>\n            <p>≥ 85% agreement with the adjudicated calibration set before\n            touching real work. In round 1 Marcus (81%) and Tom (77%)\n            <b>failed the gate</b> and were retrained; after the v2 revision all\n            three re-certified at 98%. The gate, not seniority, decides who\n            labels.</p></li>\n          <li><b>Blind triple overlap.</b>\n            <p>180 tickets — gold, calibration and 60 at random — labeled\n            independently by all three. Nobody sees a teammate’s label; there is\n            nothing to converge on but the text.</p></li>\n          <li><b>Rotated single labels in production.</b>\n            <p>The remaining 420 tickets split evenly across the crew\n            (140 each per round) — cheap, fast, and exactly where tier-2\n            sampling earns its keep.</p></li>\n          <li><b>Tier-2 senior review.</b>\n            <p>All 420 production tickets plus 29 flagged overlap cases pass the\n            QA lead; disagreements return as rework with a written cause.</p></li>\n          <li><b>Tier-3 audit.</b>\n            <p>A stratified sample of 117 final labels re-derived independently —\n            21 against gold, 96 from the v2 rules with no knowledge of the\n            crew’s answers.</p></li>\n          <li><b>Version the instructions.</b>\n            <p>v1 → calibration evidence → v2 (five rule changes, changelogued,\n            each with the ticket IDs that forced it). Guidelines are code; they\n            get reviews and releases.</p></li>\n        </ol>\n      </div>\n      <div>\n        <h3>The crew <span style="text-transform:none;letter-spacing:0;color:var(--mute)">— personas, §08</span></h3>\n        <table class="mini">\n          <thead><tr><th></th><th>persona</th><th>style</th>\n            <th>gate R1</th><th>gate R2</th></tr></thead>\n          <tbody>{persona_rows}</tbody>\n        </table>\n        <h3>Labels produced</h3>\n        <table class="mini">\n          <tbody>\n          <tr><td>Round 1 <span class="dim">(v1 rules)</span></td>\n            <td class="n">960 <span class="dim">= 320 × 3</span></td></tr>\n          <tr><td>Round 2 <span class="dim">(v2 rules)</span></td>\n            <td class="n">960 <span class="dim">= 320 × 3</span></td></tr>\n          <tr><td>Timeline rows <span class="dim">(daily, per persona)</span></td>\n            <td class="n">reconciles 1:1</td></tr>\n          </tbody>\n        </table>\n        <p class="figure-note" style="margin-top:18px">Throughput and per-persona\n        daily counts are asserted against the label files at build time —\n        <span class="mono" style="font-size:11px">results/timeline.csv</span>\n        sums exactly to the two annotation rounds.</p>\n      </div>\n    </div>\n    <figure><img src="{b64img('fig_throughput.png')}" alt="Cumulative labels per annotator, small multiples"></figure>\n  </section>\n\n  <!-- ================= 03 results ================= -->\n  <section id="s3">\n    <div class="sec-head"><span class="sec-no">03</span><h2>Results</h2>\n      <span class="hintr">overlap n = 180 · κ family</span></div>\n    <p class="lede">Round 1’s κ = {R1['fleiss_intent']:.2f} looked “acceptable”\n    and was worthless: it coexisted with a quarter of the tone traps being\n    labeled wrong <i>unanimously</i>. The revision fixed the instructions, not\n    the people.</p>\n    <figure><img src="{b64img('fig_headline.png')}" alt="Headline kappa dumbbell chart"></figure>\n\n    <div class="cols" style="margin-top:34px">\n      <div>\n        <h3>Every statistic, both rounds</h3>\n        <table class="mini">\n          <thead><tr><th>metric</th><th>R1 · v1</th><th>R2 · v2</th><th>Δ</th></tr></thead>\n          <tbody>{stat_tbl}</tbody>\n        </table>\n      </div>\n      <div>\n        <h3>Is the gain real?</h3>\n        <p class="body" style="font-size:15px">Two independent checks. The\n        round-wise 95% bootstrap CIs for Fleiss’ κ are disjoint\n        ([{ci1[0]:.3f}, {ci1[1]:.3f}] vs [{ci2[0]:.3f}, {ci2[1]:.3f}]); and a\n        <b>paired bootstrap over the same 180 items</b> — the honest test, since\n        rounds share tickets — puts Δκ at\n        <b>+{D_MEAN:.3f}, 95% CI [{D_LO:.3f}, {D_HI:.3f}]</b>, clear of\n        zero.</p>\n        <h3>Can the math be trusted?</h3>\n        <p class="body" style="font-size:15px">The statistics engine\n        (<span class="mono" style="font-size:12px">src/agreement.py</span>) is\n        written from scratch and self-tests on every build: Cohen’s κ matches\n        scikit-learn exactly; Krippendorff’s α matches NLTK under nominal\n        <i>and</i> ordinal distance in both rounds; Fleiss reproduces the\n        canonical 0.210 worked example.</p>\n        <h3>Where it still hurts</h3>\n        <p class="body" style="font-size:15px">R2 worst class is\n        <b>cancellation, κ = {min(R2['per_class_intent_kappa'].values()):.2f}</b> —\n        every class cleared 0.90. Residual risk lives in sarcasm <i>sentiment</i>\n        (unanimous {pct(R2['slices']['sarcasm']['unanimous_sentiment'], 0)}):\n        intent is solved; tone is merely contained.</p>\n      </div>\n    </div>\n\n    <div class="tabs" id="figtabs">\n      <button class="on" data-pane="p1">Per-class κ</button>\n      <button data-pane="p2">Ambiguity slices</button>\n      <button data-pane="p3">Calibration &amp; gold</button>\n    </div>\n    <div class="pane on" id="p1">\n      <figure><img src="{b64img('fig_perclass.png')}" alt="Per-class kappa dumbbell"></figure>\n      <p class="figure-note"><b>Reading:</b> R1’s average hid a localized failure —\n      cancellation κ = {R1['per_class_intent_kappa']['cancellation']:.2f} and\n      refund {R1['per_class_intent_kappa']['refund_request']:.2f}, the two classes\n      v1’s tone-first rule misrouted. Both cleared 0.90 in R2.</p>\n    </div>\n    <div class="pane" id="p2">\n      <figure><img src="{b64img('fig_slices.png')}" alt="Slice dumbbell chart"></figure>\n      <p class="figure-note"><b>Reading:</b> mixed-intent tickets went from 12%\n      unanimous to 94% — the single largest family repair. Small counts are\n      stated on the chart; slices are diagnostic, not inferential.</p>\n    </div>\n    <div class="pane" id="p3">\n      <figure><img src="{b64img('fig_gold.png')}" alt="Gold accuracy dumbbell"></figure>\n      <p class="figure-note"><b>Reading:</b> high agreement with the gold set\n      — accuracy, not just consistency. The R2 cluster at 0.96–0.99 is what the\n      tier-3 audit then confirmed on unseen samples.</p>\n    </div>\n  </section>\n\n  <!-- ================= 04 disagreement ================= -->\n  <section id="s4">\n    <div class="sec-head"><span class="sec-no">04</span><h2>Anatomy of the\n      disagreement</h2><span class="hintr">what actually broke</span></div>\n    <div class="cols wide-r">\n      <div>\n        <p class="body">Round 1’s top confusion pairs all live in the money\n        triad: cancellation↔refund (5 + 5 cases between one pair of annotators\n        alone) and billing↔refund (3). The cause was structural, not personal —\n        two v1 rules:</p>\n        <ul class="limits">\n          <li><b>Rule 4 — “tone first.”</b> Any anger was routed to\n          feedback_complaints before intent was read. Furious refund demands\n          became complaints.</li>\n          <li><b>Rule 5 — “politeness ⇒ neutral feedback.”</b> Courteous\n          delivery failures were filed as neutral. Sarcasm, being polite-shaped,\n          sailed straight through.</li>\n        </ul>\n        <p class="body" style="margin-top:18px">Version 2 replaced tone-first\n        with a money-movement test, gave sarcasm and politeness explicit\n        handling, and separated <i>asking about</i> a policy from\n        <i>demanding</i> it. Round 2 fell to five scattered mismatches for the\n        same annotator pair — no systematic pair left to fix.</p>\n      </div>\n      <div>\n        <figure style="margin-top:0"><img src="{b64img('fig_confusion.png')}" alt="Confusion grids by round"></figure>\n      </div>\n    </div>\n\n    <div class="callout">\n      <h4>The tone trap — the most important negative result in this program</h4>\n      <div class="bignums">\n        <div class="big">{pct(R1['tone_trap_slice']['unanimous_agreement'], 0)}<em>unanimous in R1</em></div>\n        <div class="vs">yet only</div>\n        <div class="big" style="color:var(--bad)">{pct(R1['tone_trap_slice']['accuracy_vs_design']['A1'], 0)}<em>matched the intended label</em></div>\n      </div>\n      <p>On the 16 engineered tone traps, all three annotators agreed on\n      three-quarters of tickets — and three-quarters of <i>those</i> agreements\n      were wrong. Perfect consensus, systematically mistaken: the textbook case\n      for scoring crews against a gold set, not against each other. After the\n      revision, tone-trap accuracy reached {pct(R2['tone_trap_slice']['accuracy_vs_design']['A1'])}\n      for every persona; κ and gold accuracy moved together, which is the only\n      kind of agreement worth paying for.</p>\n    </div>\n\n    <div class="pull">\n      <p>“Agreement ≠ correctness; the rule, not the annotators, was wrong.”</p>\n      <cite>— guidelines/annotation_guidelines_v2.md, revision table, change C1 ·\n      echoed in guidelines/CHANGELOG.md (“DELETED the tone-first rule”)</cite>\n    </div>\n\n    <figure><img src="{b64img('fig_trend.png')}" alt="Batch-level kappa trend"></figure>\n    <p class="figure-note"><b>The smell the trend chart caught:</b> in round 1,\n    κ climbed <i>within</i> the round ({R1['fleiss_intent_by_batch']['B1']:.2f} → {R1['fleiss_intent_by_batch']['B4']:.2f}) —\n    the crew was out-learning the instructions. Round 2 is flat and high: the\n    labels stopped depending on when they were produced.</p>\n  </section>\n\n  <!-- ================= 05 quality gates ================= -->\n  <section id="s5">\n    <div class="sec-head"><span class="sec-no">05</span><h2>Quality gates</h2>\n      <span class="hintr">annotator → senior → auditor</span></div>\n    <div class="cols">\n      <div>\n        <h3>What tier-2 sent back</h3>\n        <p class="body" style="font-size:15px">{REWORK_TOTAL_N}\n        of 600 tickets ({pct(QA['rework_rate_either'])}) were returned at senior\n        review — {pct(QA['rework_rate_intent_production'])} intent /\n        {pct(QA['rework_rate_sentiment_production'])} sentiment among production\n        labels. Four real cases, verbatim from the rework log:</p>\n        <ul class="limits">\n          <li><b>GF-0204</b> — “how do I see your money back policy?”\n          First pass demanded refund; review read a policy question.\n          <span class="mono" style="font-size:11px;color:var(--mute)">refund → other</span></li>\n          <li><b>GF-0291</b> — sarcasm the <i>majority</i> missed twice; the one\n          case where consensus lost to a careful reader.\n          <span class="mono" style="font-size:11px;color:var(--mute)">pos → neg</span></li>\n          <li><b>GF-0128</b> — invoice download filed as feedback.\n          <span class="mono" style="font-size:11px;color:var(--mute)">feedback → billing</span></li>\n          <li><b>GF-0090</b> — “damn invoice”: annoyance under the threshold.\n          <span class="mono" style="font-size:11px;color:var(--mute)">neu → neg</span></li>\n        </ul>\n        <p class="body" style="font-size:15px;margin-top:14px">A rework rate is a\n        steering instrument, not a grade: under ~20% the instructions are\n        basically sound; over 30% the instructions — not the crew — are the\n        defect. Ours closed at <b>{pct(QA['rework_rate_either'])}</b>.</p>\n      </div>\n      <div>\n        <h3>Rework by class — intent</h3>\n        <table class="mini">\n          <thead><tr><th>class</th><th>rate</th></tr></thead>\n          <tbody>{rework_class_rows}\n          <tr><td class="dim">all other classes</td><td class="n dim">0.0%</td></tr>\n          </tbody>\n        </table>\n        <h3>Tier-3 audit</h3>\n        <table class="mini">\n          <tbody>\n          <tr><td>final labels sampled (stratified)</td><td class="n">{QA['tier3_audit']['n']}</td></tr>\n          <tr><td class="dim">· checked against gold</td><td class="n dim">{QA['tier3_audit']['n_gold_in_audit']}</td></tr>\n          <tr><td class="dim">· re-derived from v2 independently</td><td class="n dim">{QA['tier3_audit']['n'] - QA['tier3_audit']['n_gold_in_audit']}</td></tr>\n          <tr><td>failures</td><td class="n good">0</td></tr>\n          </tbody>\n        </table>\n        <h3>What v1 would have cost</h3>\n        <p class="inlinenote">Counterfactual — replaying round-1 production\n        labels against the v2 rulebook: <b>{pct(CF['r1_production_intents_misrouted_under_v2'])}</b>\n        of intents were misrouted and <b>{pct(CF['r1_production_sentiments_corrected_under_v2'])}</b>\n        of sentiments wrong. On a 420-ticket run that is ≈\n        {round(CF['r1_production_intents_misrouted_under_v2'] * 420)} intents\n        routed to the wrong team and ≈\n        {round(CF['r1_production_sentiments_corrected_under_v2'] * 420)} tickets\n        carrying the wrong emotional read — every week, invisible to κ alone.</p>\n      </div>\n    </div>\n    <figure><img src="{b64img('fig_qa.png')}" alt="QA funnel"></figure>\n  </section>\n\n  <!-- ================= 06 evidence drawer ================= -->\n  <section id="s6">\n    <div class="sec-head"><span class="sec-no">06</span><h2>The evidence\n      drawer</h2><span class="hintr">real tickets, both rounds</span></div>\n    <p class="lede">Every claim above reduces to rows like these. Votes are the\n    raw labels from <span class="mono" style="font-size:13px">data/annotations/</span>;\n    finals come from <span class="mono" style="font-size:13px">adjudicated_labels.csv</span>.</p>\n    <table class="explorer">\n      <thead><tr><th>ticket</th><th>slice</th><th style="width:27%">text</th>\n        <th>round 1 · v1</th><th>round 2 · v2</th><th>final</th>\n        <th style="width:30%">why it’s in the drawer</th></tr></thead>\n      <tbody>{EXPLORER_HTML}</tbody>\n    </table>\n    <p class="explorer-legend"><span class="dot"></span>marks a split round\n    (intent not unanimous, or single-label production ticket) ·\n    <span class="rwmark">✳</span> final corrected at tier-2 review · intents\n    abbreviated (refund, cancel, billing…) ·\n    sentiment pos/neu/neg.</p>\n  </section>\n\n  <!-- ================= 07 reproduce ================= -->\n  <section id="s7">\n    <div class="sec-head"><span class="sec-no">07</span><h2>Reproduce it</h2>\n      <span class="hintr">everything regenerates</span></div>\n    <div class="cols">\n      <div>\n        <div class="pre"><code><span class="c"># clone &amp; install</span>\npip install -r requirements.txt\n\n<span class="c"># build the corpus (Bitext CC0 base + logged injections)</span>\nPYTHONPATH=src python src/make_dataset.py\n\n<span class="c"># run both rounds, QA tiers, audit → results/metrics.json</span>\nPYTHONPATH=src python src/simulate_pipeline.py\n\n<span class="c"># figures, this page, notebook, report.pdf</span>\nPYTHONPATH=src python src/make_figures.py\nPYTHONPATH=src python src/make_static_dashboard.py\nPYTHONPATH=src python src/build_notebook.py\nPYTHONPATH=src python src/make_report.py\n\n<span class="c"># the weekly ops view (streamlit)</span>\nstreamlit run qa-dashboard/streamlit_app.py</code></div>\n        <p class="inlinenote">Assertions — not hope — guard the pipeline: the\n        timeline reconciles 1:1 with raw labels; the paired-bootstrap CI\n        excludes zero; the from-scratch statistics match scikit-learn and NLTK\n        on every build.</p>\n      </div>\n      <div>\n        <pre class="tree">guidelineforge/\n├── guidelines/          v1.md · v2.md · CHANGELOG.md · calibration_notes.md\n├── data/\n│   ├── raw/             support_tickets.csv (600, manifest inline)\n│   ├── annotations/     round 1 &amp; 2 label files (960 rows each)\n│   ├── adjudicated_labels.csv · gold_set.csv · qa_audit_results.csv\n│   ├── for_peer_annotation/   3 sheets for real humans\n│   └── label_studio_import.json           600 tasks, tooling export\n├── src/                 pipeline: dataset, personas, agreement, QA\n├── notebooks/           agreement_analysis.ipynb (executed)\n├── results/             metrics.json · timeline.csv · figures/\n├── qa-dashboard/        this report + streamlit weekly view\n└── report.pdf           print form of §§01–08, same figures</pre>\n        <p class="inlinenote"><b>Tooling, honestly scoped:</b> the Label Studio\n        import file is generated and schema-verified (600 tasks, both label\n        dimensions, overlap pre-signing); it has not been round-tripped against\n        a live server. The peer sheets plus\n        <span class="mono" style="font-size:11.5px">src/import_peer_labels.py</span>\n        are the production path for swapping in real annotators — merge, rerun,\n        and every number on this page becomes human.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ================= 08 provenance ================= -->\n  <section id="s8">\n    <div class="sec-head"><span class="sec-no">08</span><h2>Provenance &amp;\n      limits</h2><span class="hintr">read before citing</span></div>\n    <ul class="limits">\n      <li><b>The annotators are simulations.</b> Priya, Marcus and Tom are\n      seeded engines in <span class="mono" style="font-size:13px">src/annotators.py</span>\n      with documented failure modes (skimming, tone-bias, literalism) modeled\n      on patterns every QA lead will recognize from real crews. Their\n      disagreement ceilings are designed, and the design is printed in the\n      source. This page measures <i>process</i>; it does not claim human\n      psychometrics.</li>\n      <li><b>Every statistic is recomputed from raw labels.</b> This HTML was\n      rendered from <span class="mono" style="font-size:13px">results/metrics.json</span>\n      (sha-256 <span class="mono" style="font-size:11px">{METRICS_SHA[:16]}…</span>)\n      plus the annotation CSVs. Nothing was typed by hand; prose numbers are\n      template variables.</li>\n      <li><b>One domain, one language.</b> E-commerce support, English,\n      ticket-level intent + 3-level ordinal sentiment. No spans, no hierarchy,\n      no multilingual drift — those change the tooling, not the method.</li>\n      <li><b>Gold is adjudication, not gospel.</b> The gold set was adjudicated\n      by the QA lead, not external experts; three design labels were overridden\n      by adjudication along the way (e.g. GF-0169, GF-0249). Each override is\n      in the changelog. “High agreement ≠ correctness” cuts both ways — which\n      is why tier-3 re-derives labels independently instead of trusting the\n      set.</li>\n      <li><b>Data:</b> 520 tickets from the Bitext customer-support set (CC0),\n      stratified to eight intents; 80 injected across five ambiguity families\n      and 113 sentiment re-wraps — every one logged in the augmentation\n      manifest inside <span class="mono" style="font-size:13px">src/make_dataset.py</span>.</li>\n      <li><b>What transfers to a human team:</b> the gates, the tier design,\n      the statistics engine, the calibration-first habit, the changelog\n      discipline. What does not: the specific effect sizes. Plug in the peer\n      sheets and find out.</li>\n    </ul>\n  </section>\n\n  <!-- ================= colophon ================= -->\n  <footer class="colophon">\n    <div class="drule"></div>\n    <p>GuidelineForge program report · built {_dt.date.today():%d %b %Y} from\n    raw label files · every figure and statistic regenerates via\n    <span class="mono" style="font-size:11px">src/make_*.py</span> · set in\n    Georgia &amp; system sans, charts drawn with matplotlib in a house style ·\n    no JavaScript libraries, no trackers, no external assets. Simulated-annotator\n    study — personas documented in §08 and in source.</p>\n    <p class="sig">GuidelineForge · Indore · 2026</p>\n  </footer>\n</div>\n\n<script>\n// tabs — the only JS on the page\ndocument.querySelectorAll('#figtabs button').forEach(function (b) {{\n  b.addEventListener('click', function () {{\n    document.querySelectorAll('#figtabs button').forEach(x => x.classList.remove('on'));\n    document.querySelectorAll('.pane').forEach(x => x.classList.remove('on'));\n    b.classList.add('on');\n    document.getElementById(b.dataset.pane).classList.add('on');\n  }});\n}});\n</script>\n</body></html>'''
assert f"{R1['fleiss_intent']:.4f}" in HTML_BODY and f"{R2['fleiss_intent']:.4f}" in HTML_BODY
assert 0.05 < D_MEAN < 0.2 and D_LO > 0, (D_MEAN, D_LO)
assert QA['tier3_audit']['pass_rate_overall'] == 1.0
assert 'data:image/png;base64' in HTML_BODY
for frag in ['GF-0202', 'GF-0291', 'tone trap', 'Simulation disclosure']:
    assert frag in HTML_BODY, frag
assert not HTML_BODY.count('�')
with open(OUT, 'w') as fh:
    fh.write(HTML_BODY)
size_kb = len(HTML_BODY.encode()) / 1024
print(f'wrote {OUT}  ({size_kb:.0f} KB)')
print(f'paired Δκ intent = +{D_MEAN:.3f}  95% CI [{D_LO:.3f}, {D_HI:.3f}]')
